mapper.sql:
WITH ranked AS (
        SELECT i.*,p.student_id,p.submitted_at,ROW_NUMBER() OVER(PARTITION BY p.student_id,i.question_id ORDER BY
        p.submitted_at DESC,p.id DESC,i.id DESC) rn
        FROM practice_item i JOIN practice p ON p.id=i.practice_id WHERE p.status='SUBMITTED' AND p.archived=0
        AND p.student_id=#{studentId}
        )

mapper.select:

SELECT CAST(q.id AS CHAR) questionId,q.stem,e.wrongCount,latest.is_correct latestCorrect,CAST(e.practice_id AS
CHAR) lastWrongPracticeId,CAST(e.id AS CHAR) lastWrongItemId

ORDER BY e.submitted_at DESC,e.practice_id DESC,e.id DESC LIMIT #{limit} OFFSET #{offset}
